      "아이디어를 등록하고, 제안에 투표하고, 가정 포트폴리오를 비교합니다.",
    "splash.features.6.title": "목표와 역량",
    "splash.features.6.body":
      "계획을 OKR에 맞추고 인력별 부하를 확인하며, 과다 배정은 표시됩니다.",
    "nav.tour": "둘러보기",
    "splash.hero.tour": "둘러보기 시작",
    "tour.head": "둘러보기 시작",
    "tour.toc": "이 페이지의 내용",
    "tour.open": "이 화면 열기",
    "tour.top": "맨 위로",
    "tour.start.title": "시작하기 전에",
    "tour.start.summary":
      "실제 데이터로 작업하려면 계정이 필요합니다. 로그인은 1분 이내에 끝나며 비밀번호가 필요 없습니다.",
    "tour.start.step.1":
      "오른쪽 위의 로그인을 선택하고 이메일 주소를 입력합니다.",
    "tour.start.step.2":
      "이메일로 받은 매직 링크를 엽니다. 링크는 한 번만 쓸 수 있고 곧 만료됩니다.",
    "tour.start.step.3":
      "로그인된 상태로 앱에 돌아옵니다. 기억하거나 재설정할 것이 없습니다.",
    "tour.start.step.4":
      "로그인 옆의 버튼으로 테마, 언어, 글자 크기를 바꾸거나 페이지를 공유할 수 있습니다.",
    "tour.intro":
      "계획 등록부를 단계별로 안내합니다. 계획을 만드는 방법, 인도 보드 운영, 흐름 읽기, 아이디어를 계획으로 발전시키기, 거버넌스로 계획 이끌기를 다룹니다.",
    "tour.s1.title": "계획 만들기",
    "tour.s1.summary":
      "이름과 선택 사항인 종류 레이블, 상위 계획을 지정해 계획을 등록하면 하나의 계획 트리에 자리 잡습니다.",
    "tour.s1.step.1":
      "계획을 열고 새로 만들기를 선택합니다(또는 새 계획 양식으로 바로 이동합니다).",
    "tour.s1.step.2":
      "필수인 이름을 입력하고, 선택 사항인 종류, 상태, 우선순위를 고른 뒤 코드, 소유 조직, 태그, 키워드를 추가합니다.",
    "tour.s1.step.3":
      "상위 포트폴리오(pid)를 설정해 계획을 다른 계획 안에 두고, 이미 가진 식별자를 추가합니다.",
    "tour.s1.step.4":
      "만들기를 선택합니다. 계획이 저장되고 상세 페이지로 이동합니다.",
    "tour.s2.title": "계획 찾기와 중복 처리",
    "tour.s2.summary":
      "계획 목록을 필터링하고 기록을 열어, 병합하기 전에 다른 계획과 중복되는지 확인합니다.",
    "tour.s2.step.1":
      "계획에서 그리드 필터로 이름 기준으로 목록을 좁힌 뒤 계획을 열어 종류, 상태, 코드, 소유 조직, 태그, 식별자를 확인합니다.",
    "tour.s2.step.2":
      "상세 페이지에서 중복 확인을 선택합니다. 일치 가능성이 높은 계획이 점수와 함께 중복 가능성이 있는 계획 아래에 표시됩니다.",
    "tour.s2.step.3":
      "일치하는 계획을 열어 두 계획을 비교하고, 편집으로 어느 쪽이든 기록을 바로잡습니다.",
    "tour.s2.step.4":
      "병합에서 유지할 계획 ID와 중복 계획 ID를 입력하고 미리 보기 불러오기를 선택한 뒤 병합을 선택합니다. 중복 계획은 소프트 삭제되며 최근 병합에 표시됩니다.",
    "tour.s3.title": "인도 보드 운영",
    "tour.s3.summary":
      "계획마다 칸반 보드가 있어 스프린트와 번다운으로 작업을 추적합니다.",
    "tour.s3.step.1": "계획을 열고 보드를 선택합니다.",
    "tour.s3.step.2":
      "새 작업 제목과 선택 사항인 스토리 포인트, 스프린트를 입력한 뒤 작업 추가를 선택합니다.",
    "tour.s3.step.3":
      "카드를 할 일, 진행 중, 검토 중, 완료, 차단됨 사이로 끌어 놓습니다. 끌 때마다 상태 변경으로 저장됩니다.",
    "tour.s3.step.4":
      "스프린트에서 시작일과 종료일이 있는 스프린트 이름을 입력하고 스프린트 추가를 선택합니다. 스프린트를 선택하면 번다운이 보이며, 스탠드업, 회고 메모, 속도 섹션도 사용할 수 있습니다.",
    "tour.s4.title": "계획의 흐름 읽기",
    "tour.s4.summary":
      "시간 기반 분석은 인력이 얼마나 바쁜지가 아니라 계획의 달력 시간이 어디에 쓰이는지 보여 줍니다.",
    "tour.s4.step.1": "계획을 열고 흐름을 선택합니다.",
    "tour.s4.step.2":
      "먼저 주요 타일인 서비스 수준 기대치, 흐름 효율, 최초 통과율, 진행 중인 작업을 읽습니다.",
    "tour.s4.step.3":
      "예상보다 오래 기다린 항목은 진행 중인 작업의 경과 시간에서 확인하고, 이어서 차단됨과 재작업을 살펴봅니다.",
    "tour.s4.step.4":
      "누적 흐름 기간, 제약 순위, 분포로 무엇이 인도를 늦추는지 확인합니다. 여기에는 개인 순위를 매기는 항목이 없습니다.",
    "tour.s5.title": "아이디어에서 계획으로",
    "tour.s5.summary":
      "아이디어를 등록하고 투표를 받은 뒤 제안을 거쳐 실제 계획으로 진행합니다.",
    "tour.s5.step.1":
      "아이디어를 열고 등록에 아이디어 제목과 제안 설명을 입력합니다. 위쪽 화살표로 투표하며 득표가 많은 아이디어가 먼저 표시됩니다.",
    "tour.s5.step.2":
      "전환 대상을 고르고 제안으로 전환을 선택합니다. 아무도 추진하지 않을 아이디어는 대신 기각할 수 있습니다.",
    "tour.s5.step.3":
      "제안(업무 접수)을 엽니다. 초안은 제출된 뒤 검토를 거쳐 승인되거나 반려됩니다. 중복 여부?로 중복된 수요를 확인합니다.",
    "tour.s5.step.4":
      "승인된 제안에서 승격을 선택합니다. 제안이 계획이 되고, 업무 항목 링크로 해당 계획에 이동합니다.",
    "tour.s6.title": "거버넌스로 계획 이끌기",
    "tour.s6.summary":
      "하나의 패널에 계획의 게이트, 위험, 예산, 효익, 마일스톤, 배정이 모여 있습니다.",
    "tour.s6.step.1": "계획을 열고 거버넌스를 선택합니다.",
    "tour.s6.step.2":
      "게이트 진행에서 결정(승인, 조건부 승인, 보류, 반려)을 고르고 결정 기록을 선택해 다음 게이트로 넘어갑니다.",
    "tour.s6.step.3":
      "새 위험을 제기하고 커지면 에스컬레이션합니다. 분류와 계획 금액이 있는 예산 항목을 추가하고 효익을 선언한 뒤, 발생하는 대로 실현 처리합니다.",
    "tour.s6.step.4":
      "마일스톤을 추가하고 완료 처리하며, 배정하기로 인력에 역량을 배정합니다. 일정 링크는 날짜와 의존 관계를 그려 줍니다.",
    "signin.sso": "SSO로 로그인",
    "signin.oidc": "{provider}(으)로 로그인",
    "signin.oidcError": "로그인이 완료되지 않았습니다. 다시 시도하세요.",
    "signin.oidcDenied": "로그인이 취소되었거나 조직에서 허용하지 않습니다.",
